use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut map: std::collections::HashMap<i64, i64> = std::collections::HashMap::new();

    if let Value::Array rows = input {
        for row in rows {
            if let Value::Array([key_val, value_val]) = row {
                if let Some(key) = key_val.as_i64() {
                    if let Some(value) = value_val.as_i64() {
                        map.insert(key, value);
                    }
                }
            }
        }
    }

    let mut result: Vec<Vec<Value>> = map
        .iter()
        .map(|(k, v)| vec![k.into(), v.into()])
        .collect();

    result.sort_by_key(|row| row[0].as_i64().unwrap());

    Value::Array(result.into_iter().map(|row| Value::Array(row)).collect())
}
